// babel.config.js — generated by `npx expo customize babel.config.js`; the root Jest run finds it
// (jest-expo resolves Babel options from process.cwd()).
// Stryker workers (STRYKER_MUTATOR_WORKER) compile only the files Stryker instrumented WITHOUT the
// Worklets and Reanimated plugins: Stryker injects helper functions into every mutated file, and a
// file-level 'worklet' directive would workletize them too ("stryNS_… is read-only"). Every other file
// keeps the plugins, because Reanimated needs the plugin's closure to run useAnimatedStyle(() => …)
// without a dependency array (React Compiler code never passes one). Both options must be false:
// `worklets: false` alone makes the preset add Reanimated's plugin instead.
const { readFileSync } = require('node:fs');

const STRYKER_NAMESPACE = 'stryNS_9fa48'; // written into every file Stryker mutates

function isInstrumented(filename) {
  if (filename === undefined) return false;
  try {
    return readFileSync(filename, 'utf8').includes(STRYKER_NAMESPACE);
  } catch {
    return false;
  }
}

module.exports = function (api) {
  const isMutationRun = process.env.STRYKER_MUTATOR_WORKER !== undefined;
  api.cache.using(() => isMutationRun);
  return {
    presets: ['babel-preset-expo'],
    overrides: isMutationRun
      ? [
          {
            test: isInstrumented,
            presets: [['babel-preset-expo', { worklets: false, reanimated: false }]],
          },
        ]
      : [],
  };
};
